type PrimitiveAudit = {
    readonly type: PrimitiveType;
    readonly verdict: ConformanceVerdict;
    readonly placement: PlacementVerdict;
    readonly submission: SubmissionVerdict;
    /** What the author declared, beside what the probe saw. */
    readonly declaresSubmits: boolean;
    /** The props this primitive declared it frames. Empty for almost all. */
    readonly framesProps: readonly string[];
};

type UnplacedSlots = {
    readonly type: PrimitiveType;
    readonly slots: readonly string[];
};

type UnplacedBehaviours = {
    readonly type: PrimitiveType;
    readonly behaviours: readonly BehaviourName[];
};

type ThrowingConfigurations = {
    readonly type: PrimitiveType;
    readonly failures: readonly ProbeFailure[];
    /**
     * Whether *nothing* the probe tried came back — the line between a fault the
     * audit is certain of and one it is only reporting.
     *
     * `false`: some configurations rendered and this one threw, so the component
     * is callable and a value its own schema accepts crashes it. Certain.
     *
     * `true`: every configuration threw, which is what a broken component and a
     * hook-using one both look like from outside a renderer — and a hook-using
     * component is a legitimate primitive. A host with none of those
     * asserts the whole list empty; one that ships them asserts the `false` half
     * and reads the rest.
     */
    readonly everyConfiguration: boolean;
};

type ProbeFailure = {
    readonly props: JsonObject;
    readonly reason: string;
};

type NotProbeable = {
    readonly outcome: "not-probeable";
    readonly cause: NotProbeableCause;
    readonly reason: string;
    /** Every configuration that threw. Empty exactly when nothing was called. */
    readonly failures: readonly ProbeFailure[];
};

type ConformanceVerdict = {
    readonly outcome: "decorates";
} | {
    readonly outcome: "not-decorated";
} | NotProbeable;

type PlacementVerdict = {
    readonly outcome: "probed";
    /** Declared slots that no probed configuration placed. */
    readonly unplacedSlots: readonly string[];
    /** Declared behaviours whose control no probed configuration placed. */
    readonly unplacedBehaviours: readonly BehaviourName[];
    /** Whether any probed configuration placed the children it was handed. */
    readonly rendersChildren: boolean;
    /** The configurations that answered — `{}` alone when the schema closes over nothing. */
    readonly probed: readonly JsonObject[];
    /**
     * Configurations built from the primitive's own schema that it threw on.
     * Never a reason to distrust the verdict — the configurations that
     * answered still answered — and always a fault: a component that throws
     * on a value its schema accepts is one a valid tree can crash a page with.
     */
    readonly threw: readonly ProbeFailure[];
} | NotProbeable;

type SubmissionVerdict = {
    readonly outcome: "places";
} | {
    readonly outcome: "not-placed";
} | NotProbeable;

type ColourPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
};

type ColourVerdict = {
    readonly outcome: "probed";
    /** Ink and ground both set by this primitive. */
    readonly painted: readonly ColourPairing[];
    /** Ink set here, ground left to whatever this is placed in. */
    readonly floating: readonly PaletteSlot[];
    /** Grounds this primitive puts its declared children and slots on. */
    readonly childGrounds: readonly PaletteSlot[];
} | NotProbeable;

type PrimitiveEntry = {
    readonly type: string;
    readonly description: string;
    readonly slots: readonly string[];
    readonly component: LoomPrimitive;
    readonly declaredProps: readonly CataloguedProp[] | undefined;
    /**
     * The props whose accepted values can be listed, so the conformance probe can
     * ask the primitive what it does under each one rather than under whichever
     * shape it happens to take with no props at all. Empty for the
     * primitive whose rendering does not turn on a closed choice, which is most.
     */
    readonly choices: readonly ClosedChoice[];
    /** Declared strings, keys erased alongside the props type. Empty when none. */
    readonly text: PrimitiveText<string>;
    /** Absent for the ordinary primitive, which is not a target at all. */
    readonly interactive: InteractiveWhen | undefined;
    /** `false` for the ordinary primitive, which sends nothing anywhere. */
    readonly submits: boolean;
    /** Declared framable prop names, still raw: the registry is what checks them. */
    readonly frames: readonly string[];
    /** Declared behaviour names, still raw: the registry is what checks them. */
    readonly behaviours: readonly string[];
    readonly validate: (props: JsonObject) => PropsVerdict;
};

type DerivedPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
