    readonly module: string;
    /** The exported binding: `commerce.product-card` → `commerceProductCard`. */
    readonly exportName: string;
};

type NodeTouch<Effect extends NodeEffect = NodeEffect> = {
    readonly effect: Effect;
    /**
     * Whether the operation named this node, as opposed to carrying it in.
     *
     * An insert brings a whole subtree, so every node in it was placed by that
     * revision — but only the subtree's root was asked for. "The model added a
     * card" and "the model added the heading inside the card it added" are
     * different sentences, and a reviewer deserves the one that is true.
     */
    readonly named: boolean;
    readonly entry: StoredRevision;
};

type NodeAttribution = {
    readonly outcome: "placed";
    readonly nodeId: NodeId;
    readonly placed: NodeTouch;
    /**
     * Every touch since it was placed, oldest first. Never a placement: the
     * walk stops at the one that put the node here, so anything it collected
     * on the way changed a node that was already there.
     */
    readonly since: readonly NodeTouch<NodeChange>[];
}
/** The walk reached the start of the log without finding a placement. */
 | {
    readonly outcome: "seeded";
    readonly nodeId: NodeId;
    readonly since: readonly NodeTouch<NodeChange>[];
}
/** The walk ran out of budget first. `since` is what it saw, not all there is. */
 | {
    readonly outcome: "undetermined";
    readonly nodeId: NodeId;
    readonly since: readonly NodeTouch<NodeChange>[];
};

type TreeAttribution = {
    readonly nodes: ReadonlyMap<NodeId, NodeAttribution>;
    /**
     * The oldest revision the walk read, or null when it read none.
     *
     * Reported once here rather than on every `undetermined` node, because it is a
     * fact about the read and not about any node. It is also the only thing that
     * makes an `undetermined` actionable: the node was placed at or before this.
     */
    readonly examinedTo: number | null;
    /** True when the walk saw the whole log, which is what turns unplaced into seeded. */
    readonly reachedStart: boolean;
};

type AttributionRequest = {
    /**
     * How many pages of log to read before giving up on whatever is still
     * unattributed. Every read in Loom is bounded and this one is no exception; a
     * tree edited for long enough has a history no request path should fold.
     */
    readonly pages?: number;
};

const unavailable: (cause: unknown, detail: string) => {
    readonly code: "unavailable";
    readonly detail: string;
}

type StoreError = 
/** No tree under this id — distinct from a tree with an empty history. */
{
    readonly code: "not-found";
    readonly treeId: TreeId;
} | {
    readonly code: "already-exists";
    readonly treeId: TreeId;
}
/**
 * The delta names a base revision that is not the current head. This is the
 * whole of concurrency control: two writers racing at the same base means the
 * second one is refused rather than silently applied to a tree it never saw.
 */
 | {
    readonly code: "revision-conflict";
    readonly treeId: TreeId;
    readonly expected: number;
    readonly found: number;
} | {
    readonly code: "delta-rejected";
    readonly treeId: TreeId;
    readonly error: TreeError;
} | {
    readonly code: "unavailable";
    readonly detail: string;
};

type ReplayMismatch = {
    readonly code: "delta-rejected";
    readonly revision: number;
    readonly detail: string;
}
/** A gap or a repeat in the log: revisions must be consecutive from the seed. */
 | {
    readonly code: "revision-gap";
    readonly expected: number;
    readonly found: number;
};

type ReplayedTree = {
    readonly tree: LoomTree;
    readonly idHistory: IdHistory;
};

type SnapshotAudit = {
    readonly outcome: "agrees";
    readonly revision: number;
    readonly idReturns: readonly IdReturn[];
}
/**
 * The fold produced a different tree — the drift this whole module exists for.
 *
 * Both sides are reported, not only the replayed one. The audit read the
 * snapshot to reach this verdict, and a caller that had to read it again to
 * find out *how* they differ would be comparing against a head that may have
 * moved since — so it could describe a divergence that was never the one
 * observed. `compareTrees(stored, replayed)` turns these two into something an
 * operator can act on.
 */
 | {
    readonly outcome: "diverged";
    readonly revision: number;
    readonly stored: LoomTree;
    readonly replayed: LoomTree;
    readonly idReturns: readonly IdReturn[];
} | {
    readonly outcome: "unreplayable";
    readonly mismatch: ReplayMismatch;
};

type RevertPlan = {
    readonly outcome: "revertable";
    readonly target: StoredRevision;
    /**
     * The undo, as operations. They become a delta when something applies
     * them; the id and base revision belong to that delta, not to this plan.
     */
    readonly operations: readonly TreeOperation[];
    /** The head these operations were planned against. */
    readonly headRevision: number;
    /**
     * Revisions after the target that named a node this undo touches, so
     * applying it writes over what they did. Empty for a clean undo.
     *
     * A property of the plan rather than a verdict about it: the Gate
     * decides what a contested undo is worth, and it decides it from this,
     * carried on the proposal. It travels with the plan because the delta
     * cannot show it — undoing revision 1 looks identical whether or not
     * anyone built on it.
     */
    readonly discards: readonly DiscardedWork[];
}
/** The revision is outside the span this reader and this seed can reach. */
 | {
    readonly outcome: "out-of-range";
    readonly revision: number;
    /** One past the seed: the oldest revision this seed can replay up to. */
    readonly earliest: number;
    readonly headRevision: number;
} | {
    readonly outcome: "unreplayable";
    readonly mismatch: ReplayMismatch;
}
/**
 * The target's delta cannot be inverted against the tree the replay produced.
 * In practice this means the seed is not this tree's history: inversion walks
 * the delta forward as it inverts, so a delta that applied when it was written
 * inverts against the state it was written for.
 */
 | {
    readonly outcome: "uninvertible";
    readonly revision: number;
    readonly error: TreeError;
};

type RevertTarget = {
    readonly treeId: TreeId;
    /** The revision to undo. Its delta is the one that gets inverted. */
    readonly revision: number;
    /**
     * A tree whose revision precedes the target's, to replay from. Usually
     * revision 0; a host that checkpoints may supply a later one.
     */
    readonly seed: LoomTree;
};

type RevertTargets = {
    readonly treeId: TreeId;
    readonly revisions: readonly number[];
    readonly seed: LoomTree;
};

type StoredRevision = {
    readonly treeId: TreeId;
    /** The revision this entry produced, so `revision - 1` is what it applied to. */
    readonly revision: number;
    readonly proposalId: ProposalId;
    readonly delta: TreeDelta;
    readonly provenance: Provenance;
    /** When the runtime applied it, which is not when the model produced it. */
    readonly appliedAt: string;
    /**
     * Who allowed it, when a human had to.
     *
     * Distinct from `provenance.actor`, which is who *asked*. A hold exists to put
     * a second person in the way of a change, so recording only the asker would
     * make every confirmed change look like somebody waving through their own
     * request.
     *
     * Absent on a change nobody had to allow — one the Gate accepted outright —
     * and absent on everything written before the column existed, which nobody can prove the
     * approver of. It is never back-filled: the log is append-only, and a
     * fact nobody observed does not belong in it.
     */
    readonly answeredBy?: string;
};

type AppendRequest = {
    readonly proposalId: ProposalId;
    readonly delta: TreeDelta;
    readonly provenance: Provenance;
    readonly appliedAt: string;
    /** Set only by the confirmation path; see `StoredRevision.answeredBy`. */
    readonly answeredBy?: string;
};

type TreeListing = {
    readonly treeId: TreeId;
    readonly revision: number;
};

type ListRequest = {
    /**
     * Opaque to the caller: the previous page's `cursor`, passed back unread.
     * Absent starts at the beginning. A cursor naming a tree that has since been
     * removed is not an error — listing resumes from the next key after it.
     */
    readonly cursor?: string;
    /** Clamped by the implementation — see `clampListingLimit`. */
    readonly limit?: number;
};

type TreeListPage = {
    readonly trees: readonly TreeListing[];
    /** `null` when this was the last page. */
    readonly cursor: string | null;
};

type RevisionStart = {
    /** A cursor from a previous page's `older`/`newer`, passed back unread. */
    readonly cursor?: string;
    readonly at?: never;
} | {
    /**
     * A revision to open at. **Inclusive** — the page contains it — which is
     * the difference that matters: a caller naming this has been sent to a
     * change and wants to see it, not to resume beside it.
     *
     * `direction` still says which way the rest of the page runs: `older`
     * puts the named revision at the newest end of the page, `newer` at the
     * oldest. A revision no entry holds is not an error; the page is whatever
     * falls on the named side of it, which may be empty.
     */
    readonly at?: number;
    readonly cursor?: never;
};

type RevisionReadRequest = RevisionStart & {
    /**
     * Default `newer`, which with no cursor is the oldest page — the read a fold
     * wants, and the one `auditSnapshot` takes. `older` with no cursor is the
     * newest page, which is what a reader looking at a tree asks for.
     */
    readonly direction?: PageDirection;
    readonly limit?: number;
};

type RevisionPage = PageEnds & {
    /**
     * Always ascending by `revision`, whichever end the page was taken from.
     *
     * A log is folded by `replayTree` in the order the entries were applied, and a
     * page that sometimes came back reversed would make every consumer responsible
     * for knowing which — and silently wrong when it guessed.
     */
    readonly revisions: readonly StoredRevision[];
};

interface TreeStore {
    readonly create: (tree: LoomTree) => Promise<Result<LoomTree, StoreError>>;
    readonly head: (treeId: TreeId) => Promise<Result<LoomTree, StoreError>>;
    readonly revisions: (treeId: TreeId, request?: RevisionReadRequest) => Promise<Result<RevisionPage, StoreError>>;
    readonly list: (request?: ListRequest) => Promise<Result<TreeListPage, StoreError>>;
    readonly append: (treeId: TreeId, request: AppendRequest) => Promise<Result<LoomTree, StoreError>>;
}

type WritePath = {
    readonly store: TreeStore;
    readonly holds: HoldStore;
    readonly runtime: CompositionRuntime;
};

type ProposalAnswer = {
    readonly proposalId: ProposalId;
    readonly actor?: string;
};

type WriteOutcome = {
    readonly kind: "committed";
    readonly tree: LoomTree;
    readonly proposal: ProposedChange;
    readonly disposition: Disposition;
    readonly inverse: TreeDelta;
} | {
    readonly kind: "held";
    readonly held: HeldProposal;
} | {
    readonly kind: "refused";
    readonly proposal: ProposedChange;
    readonly disposition: Disposition;
    /**
     * Why no smaller change was offered instead, when a repairer was asked for
     * one and declined. Carried straight through from the composition outcome,
     * where the three endings a refusal can have are set out.
     */
    readonly repairFailure?: InterpretationError;
} | {
    readonly kind: "not-interpreted";
    readonly error: InterpretationError;
} | {
    readonly kind: "not-applicable";
    readonly proposal: ProposedChange;
    readonly error: TreeError;
}
/** Persistence refused, including the stale-intent case that never reached a model. */
 | {
    readonly kind: "not-written";
    readonly error: StoreError;
}
/** The proposal being confirmed is not in custody — answered already, or never held. */
 | {
    readonly kind: "not-answerable";
    readonly error: HoldError;
};

type HeldProposal = {
    readonly proposalId: ProposalId;
    readonly treeId: TreeId;
    /**
     * The revision the proposal was judged against. Held separately from the
     * delta so a reader can tell a hold is stale without parsing the delta, and
     * because it is the intent's promise, not the delta's.
     */
    readonly baseRevision: number;
    /** Kept whole so a confirmation can be re-judged, and so §6 can pair ask with answer. */
    readonly intent: EditIntent;
    readonly proposal: ProposedChange;
    /** What the Gate said when it held it, so a reviewer sees the reason rather than a verdict. */
    readonly disposition: Disposition;
    readonly heldAt: string;
};

type HoldError = 
/** Nothing under this id: never held, already answered, or expired. */
{
    readonly code: "not-held";
    readonly proposalId: ProposalId;
} | {
    readonly code: "already-held";
    readonly proposalId: ProposalId;
} | {
    readonly code: "unavailable";
    readonly detail: string;
};

interface HoldStore {
    readonly hold: (held: HeldProposal) => Promise<Result<HeldProposal, HoldError>>;
    readonly get: (proposalId: ProposalId) => Promise<Result<HeldProposal, HoldError>>;
    readonly forTree: (treeId: TreeId) => Promise<Result<readonly HeldProposal[], HoldError>>;
    readonly release: (proposalId: ProposalId) => Promise<Result<HeldProposal, HoldError>>;
}

type RevertRequest = {
    readonly treeId: TreeId;
    /** The revision to undo. */
    readonly revision: number;
    /** Replayed from, to recover the tree the target's delta observed. */
    readonly seed: LoomTree;
    readonly origin: IntentOrigin;
    readonly actor?: string;
};

type RevertOutcome = WriteOutcome
/**
 * Nothing was proposed, because no undo could be computed: the revision is
 * outside the span the seed reaches, the log does not replay, or the delta does
 * not invert. Work the undo would write over is not one of these — that is a
 * proposal the Gate holds, not a plan that failed.
 */
 | {
    readonly kind: "not-revertable";
    readonly plan: UnrevertablePlan;
};

