};

type RecordedTelemetry = TelemetryRecord & {
    readonly seq: number;
    /**
     * When the journal learned of the record, which is not `occurredAt`.
     *
     * Both are here because they answer different questions and only one of them
     * the journal can vouch for. `occurredAt` is what the host said, and a host
     * that sets it wrongly — a skewed serverless clock, a replayed batch — is
     * describing its own timeline. `recordedAt` is stamped on arrival, so it is
     * the only timestamp retention may be measured against: an age a writer can
     * choose is an age a writer can dodge.
     */
    readonly recordedAt: string;
};

type TelemetryReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /** A cursor from a previous page's `older`/`newer`, passed back unread. */
    readonly cursor?: string;
    /**
     * Default `newer`, which with no cursor is the oldest page. `older` with no
     * cursor is the newest page — the read a reader almost always wants first.
     */
    readonly direction?: PageDirection;
    readonly limit?: number;
};

type TelemetryPage = PageEnds & {
    /**
     * Always ascending by `seq`, whichever end the page was taken from.
     *
     * The direction is a property of *which* records a page contains, never of
     * the order they arrive in. `episodesOf` folds a stream in arrival order, and
     * a page that sometimes came back reversed would make every consumer
     * responsible for knowing which — and silently wrong when it guessed.
     */
    readonly records: readonly RecordedTelemetry[];
};

interface TelemetryJournal {
    readonly record: (records: readonly TelemetryRecord[]) => Promise<Result<void, TelemetryError>>;
    readonly read: (request?: TelemetryReadRequest) => Promise<Result<TelemetryPage, TelemetryError>>;
    readonly forget: (request: ForgetRequest) => Promise<Result<ForgetOutcome, TelemetryError>>;
}

type RetentionPlan = {
    /**
     * Forget every record below this position. `null` when nothing may go yet —
     * either the journal holds nothing old enough, or the oldest thing in it is
     * an episode still waiting on someone.
     */
    readonly before: number | null;
    readonly forgets: number;
    /** Older than the horizon, kept because their own episode is unsettled. */
    readonly keptUnsettled: number;
    /**
     * Older than the horizon and settled, kept only because an unsettled episode
     * sits in front of them. Reported separately because it is the price of the
     * prefix rule, and a host watching this number stay large has learned that
     * something very old is still waiting on an answer.
     */
    readonly keptBehind: number;
    readonly unsettledEpisodes: number;
};

type RetentionRequest = {
    readonly policy: RetentionPolicy;
    readonly clock?: Clock;
    readonly scanLimit?: number;
};

type RetentionOutcome = {
    readonly outcome: "forgot";
    readonly plan: RetentionPlan;
    readonly removed: number;
} | {
    readonly outcome: "nothing-to-forget";
    readonly plan: RetentionPlan;
}
/** The policy or the clock was not usable. Nothing was read and nothing was deleted. */
 | {
    readonly outcome: "refused";
    readonly reason: string;
} | {
    readonly outcome: "unavailable";
    readonly error: TelemetryError;
};

type TelemetryCollector = {
    readonly sink: EventSink;
    /** Not yet written. Exposed so a host can decide a flush is worth the round trip. */
    readonly pending: () => readonly TelemetryRecord[];
    /** Records this collector could not hold or could not write. */
    readonly dropped: () => number;
    /**
     * Writes what has been collected and empties the buffer, whether or not the
     * write succeeded. Records are not retained for a retry: a journal that is
     * failing will fail the retry too, and a queue that grows while it drains
     * moves the outage into the write path.
     */
    readonly flush: () => Promise<Result<void, TelemetryError>>;
};

